# Let me check the actual text length and content more carefully
import os

file_sizes = {}
for f in os.listdir('/app/resources/'):
    if f.endswith('.txt'):
        size = os.path.getsize(f'/app/resources/{f}')
        file_sizes[f] = size

print("File sizes:")
for f, size in sorted(file_sizes.items(), key=lambda x: -x[1]):
    print(f"  {f}: {size:,} bytes")
EOF
